import{z as n,x as s,o as A,c as d,q as l,j as i,D as a,d as B,s as r,S as o,b as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"扩散模型的量化","description":"","frontmatter":{"title":"扩散模型的量化","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/diff-quantization.md","filePath":"llm/diff-quantization.md","lastUpdated":1791413859000}'),f={name:"llm/diff-quantization.md"};function p(D,E,m,C,F,h){const e=s("Mermaid");return A(),d("div",null,[E[2]||(E[2]=l('<h1 id="扩散模型的量化" tabindex="-1">扩散模型的量化 <a class="header-anchor" href="#扩散模型的量化" aria-label="Permalink to &quot;扩散模型的量化&quot;">​</a></h1><div class="epigraph"><p>扩散的误差预算要摊在几百次前向与一次解码上：去噪循环里每步省一点，解码器里错一次就全盘皆输。</p><footer>—— 据 Shang 等 PTQ4DM、Li 等 Q-Diffusion 与 SmoothQuant 一线实践整理</footer></div><p><a href="/llm/diff-step-distill-tradeoff">上一课</a>把「少跑前向」的账算清：步数与引导进了契约，收益落在交互层。本课动第二条：把每次前向跑便宜。权重与激活的量化方法学——粒度、校准、异常值迁移——在 <a href="/llm/gptq">GPTQ</a>、<a href="/llm/awq">AWQ</a>、<a href="/llm/smoothquant">SmoothQuant</a> 与<a href="/llm/num-inference-error-budget">低精度推理的误差预算</a>已立；本课只写扩散特有的部分：误差要穿过 \\(T\\) 步迭代与 VAE 解码两个放大器，校准集多了一条时间轴，三个模块的敏感度完全不同。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把 LLM 的量化流程原样搬来，会在两个地方翻车。第一，扩散激活的取值范围随时间步剧烈变化：早期步潜变量接近高斯噪声，后期步出现结构化的大幅值区域，用固定校准集一次性统计会被某几个时间步的异常值带偏，压低位宽后伪影集中爆发。第二，VAE 解码器在 fp16 下就有溢出产生黑图的先例，再压位宽时它不是「跟着主模型一起压」的对象，而是独立预算。缺口因此不是「能不能量化」，而是按模块分配精度、按时间轴做校准的协议。</p><p><span class="marginnote">「异常值迁移」翻译一下：少数激活通道数值特别大，就把大数从激活那边搬到权重那边——激活除一个数、权重乘同一个数，乘起来结果不变，但两边各自的数值范围都变平了。像把大件家具挪个房间，房子总量没变，每间房都好收拾，量化器就好办了。</span></p><h3 id="三个模块-三本账" tabindex="-1">三个模块，三本账 <a class="header-anchor" href="#三个模块-三本账" aria-label="Permalink to &quot;三个模块，三本账&quot;">​</a></h3><ul><li><strong>文本编码器</strong>：单次前向、输出是嵌入，量化收益小、风险小，是最容易的一块。</li><li><strong>去噪网络</strong>：反复执行，是省算力的主战场；权重 INT8/FP8 起步，激活看异常值分布决定是否做平滑迁移。</li><li><strong>VAE 解码器</strong>：单次执行但直通像素，误差直接变成色带与黑块，常保 fp16 甚至部分层 fp32，或用分块解码降显存。</li></ul><p><span class="marginnote">SD 的 VAE 解码在 fp16 下会因数值溢出输出黑图，社区的标准修法是解码器用 fp32 或对特定层做精度提升——量化方案里要为「解码器不动」留出显存与延迟的预算。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>协议分四步。第一步定预算：与蒸馏课同理，先决定可接受的质量下限（FID 增量、人评抽检），再选位宽，而不是先选位宽再看掉多少。第二步造校准集：提示词分布要覆盖真实流量的域，并且<strong>沿时间轴采样</strong>——每个请求的 \\(T\\) 步激活都要有机会进入统计，或按时间段分组做逐组缩放。第三步处理异常值：把大幅值从激活迁移到权重（SmoothQuant 路线），或对敏感层保留高精度。第四步联合验证：与<a href="/llm/diff-step-distill-tradeoff">步数蒸馏</a>的结论呼应，少步学生的每步误差少有后续步兜底，量化学生要一起测，不能各自达标再拼接。</p>',11)),(A(),i(o,null,{default:a(()=>[r(e,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20MOD%7B%22%E6%A8%A1%E5%9D%97%22%7D%20--%3E%20TXT%5B%22%E6%96%87%E6%9C%AC%E7%BC%96%E7%A0%81%E5%99%A8%EF%BC%9A%E6%98%93%EF%BC%8CINT8%20%E8%B5%B7%E6%AD%A5%22%5D%0A%20%20MOD%20--%3E%20UNET%5B%22%E5%8E%BB%E5%99%AA%E7%BD%91%E7%BB%9C%EF%BC%9A%E4%B8%BB%E6%88%98%E5%9C%BA%EF%BC%8C%E6%B2%BF%E6%97%B6%E9%97%B4%E8%BD%B4%E6%A0%A1%E5%87%86%22%5D%0A%20%20MOD%20--%3E%20VAE%5B%22VAE%20%E8%A7%A3%E7%A0%81%E5%99%A8%EF%BC%9A%E6%95%8F%E6%84%9F%EF%BC%8C%E4%BF%9D%E9%AB%98%E7%B2%BE%E5%BA%A6%22%5D%0A%20%20UNET%20--%3E%20CAL%5B%22%E6%A0%A1%E5%87%86%E9%9B%86%EF%BC%9A%E6%8F%90%E7%A4%BA%E8%AF%8D%E5%9F%9F%20%C3%97%20%E6%97%B6%E9%97%B4%E6%AD%A5%22%5D%0A%20%20CAL%20--%3E%20OUT%5B%22%E5%BC%82%E5%B8%B8%E5%80%BC%E8%BF%81%E7%A7%BB%E6%88%96%E6%95%8F%E6%84%9F%E5%B1%82%E4%BF%9D%E5%80%BC%22%5D%0A%20%20OUT%20--%3E%20JOINT%5B%22%E4%B8%8E%E8%92%B8%E9%A6%8F%E8%81%94%E5%90%88%E9%AA%8C%E8%AF%81%EF%BC%9AFID%20%2B%20%E4%BA%BA%E8%AF%84%22%5D%0A%20%20TXT%20--%3E%20JOINT%0A%20%20VAE%20--%3E%20JOINT%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t("h2",{id:"机制",tabindex:"-1"},[B("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=t("p",null,"为什么时间轴会让校准失真：缩放因子是从激活统计里估的，若校准批恰好集中在早期步，估出的范围覆盖不了后期步的结构化大幅值，推理时这些层饱和截断，伪影呈固定纹理出现——这就是「量化后在某些提示词上稳定出怪纹」的来源。为什么少步放大每步误差：50 步管线里单步的量化扰动被后续 49 步部分平均掉，4 步管线里同样扰动直接进图；所以步数越少，位宽预算越紧，两者是同一张误差预算表的两行。",-1)),(A(),i(o,null,{default:a(()=>[r(e,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20EAR%5B%22%E6%97%A9%E6%9C%9F%E6%AD%A5%3A%20%E6%BD%9C%E5%8F%98%E9%87%8F%E8%BF%91%E4%BC%BC%E9%AB%98%E6%96%AF%E5%99%AA%E5%A3%B0%22%5D%20--%3E%20RANGE%5B%22%E6%BF%80%E6%B4%BB%E8%8C%83%E5%9B%B4%E9%9A%8F%E6%97%B6%E9%97%B4%E6%AD%A5%E5%89%A7%E7%83%88%E5%8F%98%E5%8C%96%22%5D%0A%20%20LATE%5B%22%E5%90%8E%E6%9C%9F%E6%AD%A5%3A%20%E5%87%BA%E7%8E%B0%E7%BB%93%E6%9E%84%E5%8C%96%E5%A4%A7%E5%B9%85%E5%80%BC%22%5D%20--%3E%20RANGE%0A%20%20RANGE%20--%3E%20BAD%5B%22%E6%A0%A1%E5%87%86%E6%89%B9%E8%8B%A5%E9%9B%86%E4%B8%AD%E5%9C%A8%E6%97%A9%E6%9C%9F%E6%AD%A5%3Cbr%2F%3E%E4%BC%B0%E5%87%BA%E7%9A%84%E7%BC%A9%E6%94%BE%E7%9B%96%E4%B8%8D%E4%BD%8F%E5%90%8E%E6%9C%9F%22%5D%0A%20%20BAD%20--%3E%20SAT%5B%22%E6%8E%A8%E7%90%86%E6%97%B6%E8%BF%99%E4%BA%9B%E5%B1%82%E9%A5%B1%E5%92%8C%E6%88%AA%E6%96%AD%22%5D%0A%20%20SAT%20--%3E%20ART%5B%22%E5%9B%BA%E5%AE%9A%E7%BA%B9%E7%90%86%E4%BC%AA%E5%BD%B1%3Cbr%2F%3E%E6%9F%90%E4%BA%9B%E6%8F%90%E7%A4%BA%E8%AF%8D%E7%A8%B3%E5%AE%9A%E5%87%BA%E6%80%AA%E7%BA%B9%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=l('<p><span class="marginnote">数字感受「少步放大误差」：同样是每步千分之一量级的扰动，50 步管线里步与步方向各异、互相抵消一部分；4 步管线里几乎原样进图，而且每一步承担的信息份额还大了十几倍。这就是「步数越少、位宽预算越紧」的算术来源。</span></p><p>为什么解码器单独记账：VAE 解码把潜空间的小数值差异映射成像素的大面积色块，误差不经迭代平均、也不受日程约束，是纯的单次敏感变换。实践中「去噪压到 INT8、解码保 fp16」的组合往往比「全线 INT8」便宜得多而质量几乎无损——精度分配是钱的问题，不是荣誉问题。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重讲量化方法本身：GPTQ 的逐层误差补偿、AWQ 的激活感知缩放、FP8 的缩放格式见主干与数值课；这里只定扩散侧的分配与校准协议。量化后调度器日程不要顺手改：改了日程就引入第二个变量，归因即断。硬件相关：INT8/FP8 的收益依赖张量核支持，不支持的平台省的是显存不是时间。人评抽检不可省——FID 对高频纹理的局部退化不敏感，见本课程后面的评测课。最后，量化权重改变了底座版本谱系，与蒸馏、LoRA 的组合都要进版本号，复现性契约才守得住。</p><p><span class="marginnote">常见误区：量化完顺手把采样日程也「优化」一遍，质量掉了却说不清怪谁。量化与日程是两个变量，一次只动一个；日程改动要另走一轮门禁。这条纪律在各课反复出现，因为多人协作时它总是最先被破坏的那条。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>扩散量化按模块分配：文本编码器易、去噪网络是主战场、VAE 解码器单独保精度。</li><li>校准集多一条时间轴：激活范围随时间步剧变，固定统计会被异常步带偏。</li><li>步数与位宽共用一张误差预算表：步数越少，每步误差越少被平均，预算越紧。</li><li>解码器直通像素，fp16 都会溢出的对象不能再压；分块解码省显存不省精度。</li><li>量化与蒸馏必须联合验证，各自达标再拼接会静默劣化。</li><li>出处：Shang 等 PTQ4DM、Li 等 Q-Diffusion、Xiao 等 SmoothQuant；解码器溢出口径据 Stable Diffusion 社区实践。</li></ul>',7))])}const c=n(f,[["render",p]]);export{u as __pageData,c as default};
